script:
frappe.ui.form.on('Segment Report', {
    agency: function(frm) {
        if (frm.doc.agency) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    }
});

frappe.ui.form.on('Booking Measurement', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
                frm.set_value('contract', contract.contract);
            });
        }
    }
});

frappe.ui.form.on('Payment Tracking', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    }
});

frappe.ui.form.on('Frontline Incentive', {
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    },
    total_segments: function(frm) {
        calculate_total(frm);
    },
    rate: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    if (frm.doc.total_segments && frm.doc.rate) {
        frm.set_value('total_usd', frm.doc.total_segments * frm.doc.rate);
    }
}
